const done=id('done'), storageKey='a2-day-completed';let saved=JSON.parse(localStorage.getItem(storageKey)||'[]');
done.checked=saved.includes(D.day);done.onchange=()=>{saved=JSON.parse(localStorage.getItem(storageKey)||'[]');saved=done.checked?[...new Set([...saved,D.day])]:saved.filter(x=>x!==D.day);localStorage.setItem(storageKey,JSON.stringify(saved));syncCourseProgress()};
id('lessonTitle').textContent=D.title;id('lessonGoal').textContent=(D.goals||[]).join(' ');id('wordCount').textContent=`${D.new_vocabulary.length} new words${D.review_vocabulary.length?` · ${D.review_vocabulary.length} review`:''}`;id('grammarBadge').textContent=D.grammar.title;id('topicBadge').textContent=D.topic;
const nav=id('dayNav'),courseTiles=[];
for(let n=1;n<=30;n++){
  const available=COURSE.available.includes(n),a=document.createElement(available?'a':'span');
  a.className='day-tile';a.dataset.day=String(n);
  const number=el('span',`Day ${String(n).padStart(2,'0')}`,'day-number');
  const title=el('span',COURSE.titles[n-1]||'','day-title');
  const status=el('span','','day-status');
  if(n===D.day){a.classList.add('active');a.setAttribute('aria-current','page')}
  if(available)a.href=n===1?'index.html':`day${String(n).padStart(2,'0')}.html`;
  else a.setAttribute('aria-disabled','true');
  a.append(number,title,status);nav.append(a);courseTiles.push({n,a,status,available});
}
function syncCourseProgress(){
  const count=new Set(saved.filter(n=>Number.isInteger(n)&&n>=1&&n<=30)).size;
  id('dayProgress').textContent=`已完成 ${count} / 30 天`;
  id('courseProgress').textContent=`${count} / 30 已完成`;
  id('completionLabel').textContent=done.checked?'今日已完成':'标记完成';
  for(const tile of courseTiles){
    const complete=saved.includes(tile.n);tile.a.classList.toggle('is-complete',complete&&tile.available);
    tile.status.textContent=!tile.available?'待开放':complete?'✓ 已完成':tile.n===D.day?'正在学习':'开始练习';
    tile.a.setAttribute('aria-label',`Day ${tile.n}: ${COURSE.titles[tile.n-1]||''} · ${tile.status.textContent}`);
  }
}
syncCourseProgress();
