function addSlide(group,label,contextTitle,contextParts,makeTask){const slide=document.createElement('article');slide.className='slide';slide.hidden=true;slide.dataset.group=group;const left=document.createElement('section');left.className='context';left.append(el('div',group.startsWith('news-')?'NEWS · LISTEN & SAY':group.startsWith('listening')?'LISTEN CLOSELY':group.startsWith('reading')?'READ & DISCOVER':group.startsWith('grammar')?'GRAMMAR TOOLBOX':group==='speaking'?"LET’S TALK":'WORD EXPLORER','context-kicker'),el('h2',contextTitle));const body=document.createElement('div');body.className='context-body';for(const part of contextParts){if(part.type==='text')body.append(el('p',part.text,part.className||''));else if(part.type==='translation')body.append(translationDisclosure(part.text));else if(part.type==='block'){const b=el('div',undefined,'context-block');if(part.title)b.append(el('strong',part.title));b.append(el('span',part.text));body.append(b)}else if(part.type==='profiles'){const box=el('div',undefined,'profiles');for(const profile of part.items){const b=el('div',undefined,'context-block');b.append(el('strong',profile.label),el('span',profile.text));box.append(b)}body.append(box)}else if(part.type==='audio'){body.append(el('div',part.label,'audio-hint'));const audio=document.createElement('audio');audio.controls=true;audio.preload='metadata';audio.src=audioSource(part.src);audio.setAttribute('aria-label',part.aria||'Course recording');body.append(audio)}else if(part.type==='htmltext'){const p=el('p',part.text,'context-instructions');body.append(p)}}left.append(body);
const right=document.createElement('section');right.className='task';const head=el('div',undefined,'task-head');head.append(el('span',label,'task-kicker'),el('span','', 'question-index'));right.append(head);const content=el('div',undefined,'task-content');makeTask(content);right.append(content);slide.append(left,right);id('deck').append(slide);slides.push(slide)}
function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
