 const box=el('div',undefined,'translation-disclosure'),button=el('button','显示中文','translation-toggle'),translation=el('p',text,'context-cn');
 translation.id=`vocab-translation-${slides.length}`;translation.hidden=true;translation.setAttribute('lang','zh-CN');
 button.type='button';button.setAttribute('lang','zh-CN');button.setAttribute('aria-controls',translation.id);button.setAttribute('aria-expanded','false');
 button.onclick=()=>{translation.hidden=!translation.hidden;button.textContent=translation.hidden?'显示中文':'隐藏中文';button.setAttribute('aria-expanded',String(!translation.hidden))};
